import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, mul, add, vec2 } from 'three/tsl';
import { gsap } from 'gsap';
import { createNode as dummy } from '@/primitives';
import { createText as dummyText } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Container
  const container = new Group();

  // Geometry based on atlas region aspect ratio (512 / 320 = 1.6)
  const geometry = new PlaneGeometry(1.6, 1);

  // Base material (will receive a textured node once the texture loads)
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
  });

  const plane = new Mesh(geometry, material);
  container.add(plane);

  // Async texture load – applied when ready
  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      // Atlas region definition
      const region = {
        x: 0,
        y: 0,
        width: 512,
        height: 320,
      };

      // Fallback dimensions if the image hasn't reported size yet
      const fullW = tex.image?.width || region.width;
      const fullH = tex.image?.height || region.height;

      const repeatX = region.width / fullW;
      const repeatY = region.height / fullH;
      const offsetX = region.x / fullW;
      const offsetY = region.y / fullH;

      // UV transformation node
      const uvNode = uv();
      const transformedUV = add(mul(uvNode, vec2(repeatX, repeatY)), vec2(offsetX, offsetY));

      // Assign textured node to material
      material.map = texture(tex, transformedUV);
      material.needsUpdate = true;
    });
  }

  // No cinematic primitives to apply for this spec
  const primitiveInstances = [];

  // UserData – handlers (none) and cleanup
  container.userData = {
    handlers: {},
    cleanup: () => {
      // Dispose geometry and material
      geometry.dispose();
      material.dispose();

      // Dispose any loaded textures if they exist
      if (material.map && material.map.value && material.map.value.dispose) {
        material.map.value.dispose();
      }

      // Cleanup any primitives (none expected but safe loop)
      primitiveInstances.forEach((inst) => {
        if (inst && typeof inst.cleanup === 'function') {
          inst.cleanup();
        }
      });

      // Kill any GSAP timelines that might have been created accidentally
      gsap.killTweensOf(container);
    },
  };

  // Apply any primitives listed in config (none for this node, but guard for future)
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      const fn = ctx.primitives[primitive.name];
      if (fn) {
        const instance = fn(container, primitive.params);
        primitiveInstances.push(instance);
      }
    });
  }

  return container;
}
